  const latest = botIssueComments[botIssueComments.length - 1];
  if (latest) {
    const cleaned = latest.body.replace(/\n*---\n> 🤖 \*\*Reviewer:\*\*[\s\S]*$/m, '');
    await github.rest.issues.updateComment({
      owner, repo, comment_id: latest.id, body: cleaned + footnote,
    });
  }
  core.setFailed('Structured review JSON missing or invalid; cannot enforce the review gate.');
  return;
}
